package com.studentportal.service;
import com.studentportal.dto.AuthDtos.RegisterRequest; import com.studentportal.entity.*; import com.studentportal.repository.*; import com.studentportal.security.JwtService; import org.junit.jupiter.api.Test; import org.mockito.*; import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.crypto.password.PasswordEncoder;
import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*;
class AuthServiceTest {@Test void registerCreatesStudent(){UserRepository u=mock(UserRepository.class);StudentRepository s=mock(StudentRepository.class);PasswordEncoder e=mock(PasswordEncoder.class);AuthenticationManager a=mock(AuthenticationManager.class);JwtService j=mock(JwtService.class);when(u.existsByEmail(anyString())).thenReturn(false);when(e.encode("Password@1")).thenReturn("hash");when(u.save(any())).thenAnswer(x->x.getArgument(0));when(j.generate(anyString(),anyString())).thenReturn("jwt");AuthService svc=new AuthService(u,s,e,a,j);var out=svc.register(new RegisterRequest("Test","test@example.com","Password@1"));assertEquals("jwt",out.token());verify(s).save(any(Student.class));}}
